#include <cstdio>
#include <string>
#include <vector>
#include <queue>
#include <sstream>
#include <iostream>

struct Node {
    int val;
    Node *left, *right;
    Node(int v) : val(v), left(nullptr), right(nullptr) {}
};

bool mirror(Node* a, Node* b) {
    if (!a && !b) return true;
    if (!a || !b) return false;
    return a->val == b->val && mirror(a->left, b->right) && mirror(a->right, b->left);
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    std::vector<std::string> tok;
    std::string t;
    while (iss >> t) tok.push_back(t);
    if (tok.empty() || tok[0] == "null") { printf("YES\n"); return 0; }

    std::vector<Node*> nodes(tok.size(), nullptr);
    nodes[0] = new Node(std::stoi(tok[0]));
    std::queue<int> q;
    q.push(0);
    size_t i = 1;
    while (!q.empty() && i < tok.size()) {
        int idx = q.front(); q.pop();
        if (i < tok.size()) {
            if (tok[i] != "null") {
                nodes[i] = new Node(std::stoi(tok[i]));
                nodes[idx]->left = nodes[i];
                q.push((int)i);
            }
            ++i;
        }
        if (i < tok.size()) {
            if (tok[i] != "null") {
                nodes[i] = new Node(std::stoi(tok[i]));
                nodes[idx]->right = nodes[i];
                q.push((int)i);
            }
            ++i;
        }
    }
    printf("%s\n", mirror(nodes[0]->left, nodes[0]->right) ? "YES" : "NO");
    return 0;
}
